from jsonb_to_recordset($dados$[{"item_group_id": "OLD-P1001", "id_loja": "1001", "nome": "Camisa Argentina Retrô 1986 Away - Masculino", "slug": "camisa-argentina-retr-1986-away-masculino", "url": "https://www.oldensports.com.br/camisa-argentina-retr-1986-away-masculino", "marca": "Retrômania", "categoria": "Camisa", "departamento": "camisas", "clube": "Argentina", "genero": "masculino", "faixa_etaria": "adulto", "descricao": "Camisa Argentina Retrô 1986 Away - Masculino\nReviva a magia da Copa do Mundo de 1986 com a camisa retrô da seleção argentina, uma homenagem ao uniforme reserva usado durante a campanha histórica. Produzida em poliéster de alta qualidade, esta peça oferece conforto e durabilidade, perfeita para o dia a dia ou para colecionadores apaixonados.\nO design em azul clássico destaca-se pelas listras verticais discretas, enquanto o escudo bordado da AFA adiciona autenticidade e elegância. Esta camisa é um símbolo de um dos momentos mais memoráveis do futebol, sendo ideal para fãs que desejam celebrar a conquista da Argentina em grande estilo.\n- Produto Oficial Licenciado Asociación del Fútbol Argentino.\nCaracterística:\n- Jacquard 100% poliéster\n- Escudo bordado em alta definição\n- Manga: Curta\n- Gola: V\nDimensões Aproximadas (A x L):\nP: 67 x 49 cm\nM: 69 x 51 cm\nG: 71 x 53 cm\nGG: 73 x 55 cm\nEG: 75 x 57 cm", "medidas": null, "preco": 159.9, "preco_promocional": null, "preco_pix": 151.91, "parcelamento": "6x de R$ 26,65 Sem juros", "imagens": [{"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_argentina_retr_1986_away_masculino_1_20260123142316_a3f195322515.jpg", "tipo": "frente"}, {"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_argentina_retr_1986_away_masculino_2_20260123142316_bf5aec0d3edc.jpg", "tipo": "extra"}, {"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_argentina_retr_1986_away_masculino_3_20260123142316_671131e66b0e.jpg", "tipo": "extra"}, {"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_argentina_retr_1986_away_masculino_4_20260123142316_dec763179d4c.jpg", "tipo": "extra"}], "video_url": null, "propriedades": {"Categoria": ["Camisa"], "Clubes": ["Argentina"], "Gênero": ["Masculino"]}, "lancamento": false, "destaque": false, "coletado_em": "2026-11-24T20:16:44.930870+00:00"}, {"item_group_id": "OLD-P101", "id_loja": "101", "nome": "Camisa Flamengo Retrô Zico Libertadores 1981 Com  Assinatura Algodão - Masculino", "slug": "camisa-flamengo-retr-zico-libertadores-1981-com-assinatura-algodo-masculino", "url": "https://www.oldensports.com.br/camisa-flamengo-retr-zico-libertadores-1981-com-assinatura-algodo-masculino", "marca": "Braziline", "categoria": "Camisa", "departamento": "camisas", "clube": "Flamengo", "genero": "masculino", "faixa_etaria": "adulto", "descricao": "Camisa Flamengo Retrô Zico Libertadores 1981 Com Assinatura Algodão - Masculino\nA camisa do Flamengo Zico Libertadores 1981 é o verdadeiro manto sagrado, a pedida certa para os torcedores vestirem sua paixão pelo Mengão.\nDo lado esquerdo do tórax traz o escudo do Mengão e do lado oposto conta com a assinatura do ídolo Zico. Nas costas trás o número 10 que o craque vestia.\nProduzida em 100% algodão, a camiseta oferece maciez, durabilidade e muito conforto para seus torcedores.\n- Produto Oficial Licenciado Flamengo\ninformações Adicionais:\nMaterial: 100% algodão\nEscudo: Bordado\nManga: Curta\nGola: Decote V\nMedidas aproximadas ( A x L ):\nP: 69 x 50cm\nM: 71 x 52cm\nG: 73 x 54cm\nGG: 75 x 56cm\nXG: 78 x 62cm", "medidas": "Medidas aproximadas ( A x L ):\nP: 69 x 50cm\nM: 71 x 52cm\nG: 73 x 54cm\nGG: 75 x 56cm\nXG: 78 x 62cm", "preco": 209.9, "preco_promocional": 189.9, "preco_pix": 180.41, "parcelamento": "6x de R$ 31,65 Sem juros", "imagens": [{"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_flamengo_retro_zico_libertadores_1981_com_assinatura_algodao_masculino_101_1_25ceba1fed53a6290bd90d7b703a3977.jpg", "tipo": "frente"}, {"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_flamengo_retro_zico_libertadores_1981_com_assinatura_algodao_masculino_101_2_2d0ba0d68a7e222faa63e8535a13358c.jpg", "tipo": "extra"}, {"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_flamengo_retro_zico_libertadores_1981_com_assinatura_algodao_masculino_101_3_23097e4f379e8f9801de289cfe2f4d01.jpg", "tipo": "extra"}, {"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_flamengo_retro_zico_libertadores_1981_com_assinatura_algodao_masculino_101_4_249c62c78d019be1b53bce8381bbc9a8.jpg", "tipo": "extra"}], "video_url": null, "propriedades": {"Categoria": ["Camisa"], "Clubes": ["Flamengo"], "Gênero": ["Masculino"]}, "lancamento": false, "destaque": false, "coletado_em": "2026-11-24T20:16:44.930870+00:00"}, {"item_group_id": "OLD-P1023", "id_loja": "1023", "nome": "Conjunto Corinthians Camisa + Shorts Recortes Número 10 - Infantil", "slug": "conjunto-corinthians-camisa-shorts-recortes-nmero-10-infantil", "url": "https://www.oldensports.com.br/conjunto-corinthians-camisa-shorts-recortes-nmero-10-infantil", "marca": "Coimbra", "categoria": "Kits", "departamento": "kits", "clube": "Corinthians", "genero": "infantil", "faixa_etaria": "infantil", "descricao": "Conjunto Corinthians Camisa + Shorts Recortes Número 10 - Infantil\nO conjunto infantil do Corinthians é a escolha perfeita para os pequenos torcedores que já vibram com o Timão. Composto por camisa e shorts, o modelo traz o clássico design em preto e branco que representa a tradição do clube.\nA camisa, confeccionada em poliéster leve e confortável, exibe o escudo oficial estampado no peito e o número 10 nas costas, inspirado nos grandes ídolos corinthianos. Já o shorts, também em poliéster, conta com o número 10 na parte frontal e cordão de ajuste para garantir melhor adaptação ao corpo. Um conjunto completo que une estilo, conforto e paixão pelo futebol desde cedo.\nProduto Oficial Licenciado Corinthians\nInformações Adicionais\nEscudo: Estampado\nMangas: Curtas\nGola: Redonda\nTecido: 100% Poliéster\nMedidas Aproximadas A X L (Camisa)\n04: 50 x 38cm\n06: 53 x 40cm\n08: 55 x 42cm\nMedidas Aproximadas A X L (Shorts)\n04: 22 x 39cm\n06: 23 x 40cm\n08: 26 x 42cm", "medidas": "Medidas Aproximadas A X L (Camisa)\n04: 50 x 38cm\n06: 53 x 40cm\n08: 55 x 42cm\nMedidas Aproximadas A X L (Shorts)\n04: 22 x 39cm\n06: 23 x 40cm\n08: 26 x 42cm", "preco": 159.9, "preco_promocional": null, "preco_pix": 151.91, "parcelamento": "6x de R$ 26,65 Sem juros", "imagens": [{"url": "https://images.tcdn.com.br/img/img_prod/1445347/conjunto_corinthians_camisa_shorts_recortes_nmero_2_20260923120956_92123de598b4.jpg", "tipo": "frente"}, {"url": "https://images.tcdn.com.br/img/img_prod/1445347/conjunto_corinthians_camisa_shorts_recortes_nmero_1_20260923120956_06bde76df0ea.jpg", "tipo": "extra"}, {"url": "https://images.tcdn.com.br/img/img_prod/1445347/conjunto_corinthians_camisa_shorts_recortes_nmero_3_20260923120956_a5ed9e845eac.jpg", "tipo": "extra"}, {"url": "https://images.tcdn.com.br/img/img_prod/1445347/conjunto_corinthians_camisa_shorts_recortes_nmero_4_20260923120956_c4ba8c10f73b.jpg", "tipo": "extra"}], "video_url": "https://www.youtube.com/embed/wVU3qSTYdy4", "propriedades": {"Categoria": ["Kits"], "Clubes": ["Corinthians"], "Gênero": ["Infantil"]}, "lancamento": false, "destaque": false, "coletado_em": "2026-11-24T20:16:44.930870+00:00"}, {"item_group_id": "OLD-P1025", "id_loja": "1025", "nome": "Conjunto PSG Símbolo Mini Craque - Camisa + Shorts - Infantil", "slug": "conjunto-psg-smbolo-mini-craque-camisa-shorts-infantil", "url": "https://www.oldensports.com.br/conjunto-psg-smbolo-mini-craque-camisa-shorts-infantil", "marca": "Braziline", "categoria": "Kits", "departamento": "kits", "clube": "PSG", "genero": "infantil", "faixa_etaria": "infantil", "descricao": "Conjunto PSG Símbolo Mini Craque - Camisa + Shorts - Infantil\nTransforme o dia a dia da criançada com o estilo e a paixão de um dos maiores clubes do mundo! O conjunto infantil 